-- ---------------------------------------------------------------------------------------
-- Class trainers (2600200-2600208) and profession masters (2600300-2600313).
--
-- Run against tw_world. IDEMPOTENT. Requires a mangosd RESTART.
-- Summon with `.npc summon <entry>`.
-- GENERATED by scratchpad/gen_npcs.py - edit that and regenerate, not this file.
--
-- WHY ONE NPC PER CLASS
--   Creature::IsTrainerOf enforces an exact match for TRAINER_TYPE_CLASS:
--       if (pPlayer->GetClass() != GetCreatureInfo()->trainer_class) ...refuse...
--   No bypass exists, so a single all-class trainer is impossible. Nine NPCs.
--
--   The profession gate is looser:
--       if (GetCreatureInfo()->trainer_spell && !pPlayer->HasSpell(...)) ...refuse...
--   Note `trainer_spell &&` - setting it to 0 skips the check entirely, so a profession
--   master serves anyone. That also keeps these working if the start-with-professions
--   grant is ever reverted.
--
-- NPC FLAGS IN THIS CORE (UnitDefines.h:446-450)
--   GOSSIP 0x01, QUESTGIVER 0x02, VENDOR 0x04, TRAINER 0x10.
--   19 = gossip+questgiver+trainer, matching the stock warrior trainers.
--   23 = that plus vendor, for the profession masters.
--   VENDOR is 0x04 here, NOT stock MaNGOS's 0x80 - using 0x80 gives an NPC whose vendor
--   window silently never opens.
--
-- WHY CLONE-THEN-UPDATE
--   A first attempt enumerated creature_template's columns in INSERT..SELECT and failed:
--   this core has display_id1, not modelid_1. Cloning the whole row with LIKE + SELECT *
--   and then UPDATEing only the fields that differ needs no column list at all.
--
-- NO TRAINER LIST CAP
--   Unlike vendors (MAX_VENDOR_ITEMS 128, which truncates silently), SMSG_TRAINER_LIST
--   carries a uint32 count and the core imposes no limit, so ~190 spells is fine.
-- ---------------------------------------------------------------------------------------

USE tw_world;

DELETE FROM creature_template          WHERE entry BETWEEN 2600200 AND 2600399;
DELETE FROM npc_trainer                WHERE entry BETWEEN 2600200 AND 2600399;
DELETE FROM npc_vendor                 WHERE entry BETWEEN 2600200 AND 2600399;
DELETE FROM creature_questrelation     WHERE id    BETWEEN 2600200 AND 2600399;
DELETE FROM creature_involvedrelation  WHERE id    BETWEEN 2600200 AND 2600399;

DROP TEMPORARY TABLE IF EXISTS tmp_npc;
CREATE TEMPORARY TABLE tmp_npc LIKE creature_template;

